# Find all surrounded single-cell 0-regions
print("=== Finding surrounded single-cell 0-regions ===")
from collections import deque

def find_all_0_regions(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not visited[r][c]:
                region = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.append(region)

    return regions

